import{_ as a,o as i,c as t,ag as r}from"./chunks/framework.ePeAWSvT.js";const u=JSON.parse('{"title":"Media Processing","description":"Supported formats, derivative generation rules, and video playback strategy in Foldergram.","frontmatter":{"title":"Media Processing","description":"Supported formats, derivative generation rules, and video playback strategy in Foldergram."},"headers":[],"relativePath":"media-processing.md","filePath":"media-processing.md","lastUpdated":1793727298000}'),d={name:"media-processing.md"};function o(s,e,n,l,c,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="media-processing" tabindex="-1">Media Processing <a class="header-anchor" href="#media-processing" aria-label="Permalink to &quot;Media Processing&quot;">​</a></h1><p>Foldergram generates derivatives so feed and detail views can stay fast without touching original files on every request. Depending on configuration, those derivatives are either created during scans or lazily on first request and then cached on disk.</p><h2 id="supported-formats" tabindex="-1">Supported formats <a class="header-anchor" href="#supported-formats" aria-label="Permalink to &quot;Supported formats&quot;">​</a></h2><h3 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h3><ul><li><code>.jpg</code></li><li><code>.jpeg</code></li><li><code>.png</code></li><li><code>.webp</code></li><li><code>.gif</code></li><li><code>.avif</code></li></ul><h3 id="videos" tabindex="-1">Videos <a class="header-anchor" href="#videos" aria-label="Permalink to &quot;Videos&quot;">​</a></h3><ul><li><code>.mp4</code></li><li><code>.mov</code></li><li><code>.m4v</code></li><li><code>.webm</code></li><li><code>.mkv</code></li></ul><h2 id="output-sizes" tabindex="-1">Output sizes <a class="header-anchor" href="#output-sizes" aria-label="Permalink to &quot;Output sizes&quot;">​</a></h2><p>Image sizing values are defined in <code>server/src/utils/image-utils.ts</code>. Video direct-playback limits are defined in <code>server/src/utils/video-playback-policy.ts</code>.</p><table tabindex="0"><thead><tr><th>Constant</th><th>Value</th><th>Used for</th></tr></thead><tbody><tr><td><code>THUMBNAIL_SIZE</code></td><td><code>640</code></td><td>Feed cards, folder grids, avatars, and video posters</td></tr><tr><td><code>PREVIEW_MAX_WIDTH</code></td><td><code>1500</code></td><td>Detail-view image previews and animated AVIF preview width</td></tr><tr><td><code>DIRECT_VIDEO_PLAYBACK_MAX_BYTES</code></td><td><code>24 * 1024 * 1024</code></td><td>Largest source file that may play directly</td></tr><tr><td><code>DIRECT_VIDEO_PLAYBACK_MAX_DISPLAY_WIDTH</code></td><td><code>1500</code></td><td>Widest orientation-correct display width that may play directly</td></tr></tbody></table><h2 id="derivative-timing" tabindex="-1">Derivative timing <a class="header-anchor" href="#derivative-timing" aria-label="Permalink to &quot;Derivative timing&quot;">​</a></h2><p><code>DERIVATIVE_MODE</code> controls when missing derivatives are created:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Behavior</th></tr></thead><tbody><tr><td><code>eager</code></td><td>Scans queue required thumbnails and previews during indexing. Qualifying direct-playback videos still receive posters but skip the playable preview.</td></tr><tr><td><code>lazy</code></td><td>Scans index metadata only. Missing thumbnails and required previews are generated when <code>/thumbnails/...</code> or <code>/previews/...</code> is first requested.</td></tr></tbody></table><p>Lazy mode still writes the generated files to the configured derivative directories, so subsequent requests use the cached file on disk. It also uses the same media-specific generation rules as eager mode, including animated AVIF preview generation and the direct-playback video policy.</p><p>For an eligible direct-playback video, a request to a previously issued <code>/previews/...mp4</code> URL resolves to the indexed original instead of recreating a preview. Folder-share preview routes remain scoped to generated media and can create a shared preview on authorized first access.</p><h2 id="scan-time-media-failures" tabindex="-1">Scan-time media failures <a class="header-anchor" href="#scan-time-media-failures" aria-label="Permalink to &quot;Scan-time media failures&quot;">​</a></h2><p><code>SCAN_MEDIA_ERROR_MODE</code> controls what happens when supported media reaches scan processing but fails during stat, metadata, derivative generation, or derivative-repair work.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Behavior</th></tr></thead><tbody><tr><td><code>skip</code></td><td>Report the failure, skip that file, continue scanning, and finish the run as <code>completed_with_errors</code>.</td></tr><tr><td><code>fail</code></td><td>Stop on the first such failure and mark the run as failed.</td></tr></tbody></table><p>In skip mode, Foldergram keeps a short admin-visible sample in SQLite and writes the full per-run report under <code>&lt;DATA_ROOT&gt;/scan-errors/</code>.</p><p>This applies to supported image and video files that actually reach scan processing. Unsupported extensions are still ignored earlier during discovery.</p><h2 id="derivative-mapping" tabindex="-1">Derivative mapping <a class="header-anchor" href="#derivative-mapping" aria-label="Permalink to &quot;Derivative mapping&quot;">​</a></h2><p>Foldergram stores derivatives by stable asset key, not by source-relative path. Thumbnails and previews share the same shard layout so a media item keeps the same derivative location even when its source folder path changes. The current layout uses a single shard segment based on the first two hex characters of <code>asset_key</code>.</p><table tabindex="0"><thead><tr><th>Source media</th><th>Thumbnail output</th><th>Preview output</th></tr></thead><tbody><tr><td>Image</td><td><code>.webp</code></td><td><code>.webp</code></td></tr><tr><td>Video</td><td><code>.webp</code></td><td><code>.mp4</code> or direct original playback</td></tr></tbody></table><p>Examples:</p><table tabindex="0"><thead><tr><th>Source</th><th>Thumbnail</th><th>Preview</th></tr></thead><tbody><tr><td><code>trips/oslo/IMG_0001.jpg</code></td><td><code>ab/abcd1234....webp</code></td><td><code>ab/abcd1234....webp</code></td></tr><tr><td><code>trips/oslo/clip-01.mov</code></td><td><code>ef/ef01abcd....webp</code></td><td><code>ef/ef01abcd....mp4</code></td></tr></tbody></table><p>Existing libraries are migrated in place on the next full scan after upgrade. Old mirrored derivative paths keep working until that migration completes. If a stored derivative path points at a missing file during the upgrade, Foldergram keeps the last known-good path until the new target is repaired or regenerated.</p><h2 id="image-derivatives" tabindex="-1">Image derivatives <a class="header-anchor" href="#image-derivatives" aria-label="Permalink to &quot;Image derivatives&quot;">​</a></h2><p>Most images are processed with Sharp. Static AVIF files also stay on the Sharp path so transparency and regular image behavior are preserved.</p><h3 id="thumbnail" tabindex="-1">Thumbnail <a class="header-anchor" href="#thumbnail" aria-label="Permalink to &quot;Thumbnail&quot;">​</a></h3><ul><li>auto-rotated</li><li>resized to width <code>640</code> without enlargement</li><li>encoded as WebP with <code>quality: 82</code></li></ul><h3 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h3><ul><li>auto-rotated</li><li>resized to width <code>1500</code> without enlargement</li><li>encoded as WebP with <code>quality: 86</code></li></ul><h2 id="animated-avif-handling" tabindex="-1">Animated AVIF handling <a class="header-anchor" href="#animated-avif-handling" aria-label="Permalink to &quot;Animated AVIF handling&quot;">​</a></h2><p>Animated AVIF image sequences are treated as images in the UI, not videos.</p><p>Foldergram uses:</p><ul><li>Sharp first for normal static AVIF image metadata</li><li><code>ffprobe</code> to identify animated AVIF image sequences when Sharp cannot decode them reliably</li><li><code>ffmpeg</code> to generate static WebP thumbnails and animated WebP previews for animated AVIF files</li></ul><p>This hybrid path keeps static AVIF on the normal Sharp image pipeline while still supporting animated AVIF sequences that Sharp cannot decode reliably in the current runtime.</p><p>Existing libraries with already indexed AVIF files receive a one-time AVIF metadata repair on the next successful full scan after upgrade, including <strong>Scan for changes</strong> even when folder contents are unchanged. That pass refreshes legacy animated flags and AVIF timestamp fallbacks for stored rows, then stops re-reading unchanged AVIF files on later scans. If metadata inspection fails, the repair stays pending for a later scan.</p><h2 id="image-detail-source" tabindex="-1">Image detail source <a class="header-anchor" href="#image-detail-source" aria-label="Permalink to &quot;Image detail source&quot;">​</a></h2><p><code>IMAGE_DETAIL_SOURCE</code> affects image detail pages only:</p><table tabindex="0"><thead><tr><th>Value</th><th>Behavior</th></tr></thead><tbody><tr><td><code>preview</code></td><td><code>/image/:id</code> uses the generated preview asset.</td></tr><tr><td><code>original</code></td><td><code>/image/:id</code> uses <code>/api/originals/:id</code> for images.</td></tr></tbody></table><p>This setting does not change feed cards, folder grids, avatars, or any video playback behavior.</p><h2 id="video-metadata" tabindex="-1">Video metadata <a class="header-anchor" href="#video-metadata" aria-label="Permalink to &quot;Video metadata&quot;">​</a></h2><p>Videos are probed with <code>ffprobe</code>.</p><p>Foldergram reads:</p><ul><li>width and height</li><li>duration</li><li>creation timestamps when present</li><li>container and codec details used to decide playback strategy</li></ul><h2 id="video-thumbnail-generation" tabindex="-1">Video thumbnail generation <a class="header-anchor" href="#video-thumbnail-generation" aria-label="Permalink to &quot;Video thumbnail generation&quot;">​</a></h2><p>Video thumbnails are generated with <code>ffmpeg</code>:</p><ul><li><code>thumbnail</code> filter picks a representative frame</li><li>the frame is resized to width <code>640</code></li><li>output is encoded as WebP</li></ul><h2 id="video-preview-generation" tabindex="-1">Video preview generation <a class="header-anchor" href="#video-preview-generation" aria-label="Permalink to &quot;Video preview generation&quot;">​</a></h2><p>A video needs a derived preview when it is not eligible for direct playback under the policy below, or when an active folder share requires a scoped preview. Foldergram transcodes that preview with <code>ffmpeg</code> to:</p><ul><li>H.264 video</li><li>AAC audio when audio is present</li><li><code>yuv420p</code></li><li><code>+faststart</code></li><li>landscape-equivalent output up to <code>1280x720</code></li><li>portrait and square output that keeps the short edge at or below <code>720</code></li><li>even-numbered output dimensions for encoder compatibility</li></ul><p>Audio selection uses the first audio stream, in source stream order, whose codec has a decoder in the installed FFmpeg build. Unsupported tracks are skipped; only the selected track is encoded to AAC. Videos without audio remain silent. If audio tracks exist but none has an available decoder, generation fails and reports an error instead of silently dropping all audio. Decoder availability does not guarantee a damaged track can decode; conversion errors still fail the preview and remain visible in scan reports.</p><p>Video previews are written to unique temporary MP4 files beside the destination. After successful conversion, Foldergram checks that the output is nonempty and FFprobe reports an MP4 with H.264/yuv420p video, positive dimensions and duration, and the expected AAC audio. It then atomically replaces the cached preview. Failures remove temporary output and preserve an existing preview.</p><p>Empty derivative files are treated as missing during generation, migration, repair scans, and lazy requests. Cache reads check file size without probing media on every request. Nonempty legacy files are trusted; a nonempty corrupt or truncated legacy preview requires forced regeneration. The publication probe checks container and stream metadata, rather than decoding the full output.</p><h2 id="direct-original-video-playback" tabindex="-1">Direct-original video playback <a class="header-anchor" href="#direct-original-video-playback" aria-label="Permalink to &quot;Direct-original video playback&quot;">​</a></h2><p>Foldergram can use the original video as the ordinary playback source when all of these are true:</p><ul><li>the file extension is <code>.mp4</code></li><li>the container is compatible with MP4</li><li>the video codec is H.264</li><li>the pixel format is <code>yuv420p</code></li><li>the audio codec is AAC, or there is no audio track</li><li>the source size is known, positive, and at most <code>24 MiB</code> inclusive</li><li>the orientation-correct display width is known, positive, and at most <code>1500</code> pixels inclusive</li></ul><p>Unknown or incomplete compatibility metadata conservatively keeps the generated preview until a later indexing or backfill pass can establish eligibility. The width budget uses display width, so rotated and portrait videos follow the same orientation-correct dimensions shown by the app. It is not a bitrate or pixel-count limit.</p><p>When a video qualifies:</p><ul><li>Foldergram still generates the thumbnail/poster.</li><li>Normal playback uses the indexed original-media endpoint. For example, <code>previewUrl</code> resolves to <code>/api/originals/:id</code>.</li><li><code>playbackStrategy</code> continues to report original-playback compatibility.</li><li><code>videoPlaybackSource</code> reports the selected ordinary source as <code>original</code>.</li><li>Feed cards, folder pages, Reels, stories, likes, collections, and Carousel members use that same selected source.</li><li>The detail player does not show an HD switch when playback is already the original. Larger compatible videos that use a generated preview keep the existing preview/HD switch behavior.</li></ul><p>When a video is above either budget, or compatibility metadata does not qualify:</p><ul><li>A generated preview remains required for ordinary playback.</li><li><code>videoPlaybackSource</code> is <code>preview</code>.</li><li>The original may still be offered through the detail player&#39;s HD switch when <code>playbackStrategy</code> is <code>original</code>.</li></ul><h3 id="folder-shares" tabindex="-1">Folder shares <a class="header-anchor" href="#folder-shares" aria-label="Permalink to &quot;Folder shares&quot;">​</a></h3><p>Folder-share visitors do not receive ordinary <code>/api/originals/:id</code> access. Shared payloads continue to use <code>/api/share/images/:id/preview</code>. A qualifying video may still need a generated preview when a folder has an active, unexpired link share or a configured share password. Eager processing of new or repaired media can create or retain those shared previews. Lazy shared delivery can create one on authorized first access.</p><h3 id="upgrade-old-urls-and-reclamation" tabindex="-1">Upgrade, old URLs, and reclamation <a class="header-anchor" href="#upgrade-old-urls-and-reclamation" aria-label="Permalink to &quot;Upgrade, old URLs, and reclamation&quot;">​</a></h3><p>Existing indexed metadata is enough to select originals. No library rebuild or all-library FFprobe pass is required.</p><p>Previously issued normal <code>/previews/...mp4</code> URLs keep working in both eager and lazy modes. For a currently eligible asset, the preview URL resolves to the same original-media serving path. The response does not use the immutable derivative cache policy because it is serving a mutable original. It uses revalidation-friendly caching (<code>private, no-cache</code> with <code>Vary: Cookie</code> when password protection is enabled, or <code>public, no-cache</code> otherwise) while preserving <code>ETag</code>, <code>Last-Modified</code>, and byte-range behavior.</p><p><strong>Scan and repair derivatives</strong> reclaims obsolete video previews for already-indexed qualifying videos. It validates the current source, checks live derivative references and active share requirements, and removes only the generated preview file. Thumbnails and originals are preserved. Quick scans do not perform this bulk cleanup.</p><p>When a source video changes, both scan modes invalidate its previous generated preview, including when the replacement qualifies for direct playback. A folder share enabled afterward generates a preview from the replacement. Repair scans also recheck share requirements immediately before removing an obsolete preview, so links or passwords enabled during source validation retain the cached file.</p><p>During derivative-layout migration and repair, an intentionally absent normal video preview is treated as expected rather than as corruption, so it does not trigger repeated transcoding or prevent migration completion.</p><h2 id="gif-handling" tabindex="-1">GIF handling <a class="header-anchor" href="#gif-handling" aria-label="Permalink to &quot;GIF handling&quot;">​</a></h2><p>GIF files are accepted as supported images, but derivatives are generated with <code>animated: false</code>. In practice that means Foldergram treats GIF derivatives as static image outputs, not animated preview pipelines.</p><h2 id="timestamp-sources" tabindex="-1">Timestamp sources <a class="header-anchor" href="#timestamp-sources" aria-label="Permalink to &quot;Timestamp sources&quot;">​</a></h2><p>Foldergram resolves <code>taken_at</code> from the best available source:</p><ul><li>EXIF or embedded media metadata when available</li><li>file modification time or first-seen timing when richer metadata is absent</li></ul><p>Those timestamps influence:</p><ul><li>Recent feed ordering</li><li>Moments eligibility</li><li>Highlights fallback behavior</li></ul><h2 id="thumbnail-only-rebuild" tabindex="-1">Thumbnail-only rebuild <a class="header-anchor" href="#thumbnail-only-rebuild" aria-label="Permalink to &quot;Thumbnail-only rebuild&quot;">​</a></h2><p>The thumbnail rebuild action:</p><ul><li>removes the thumbnail cache directory</li><li>recreates it</li><li>rebuilds thumbnails and video poster images for currently indexed media</li></ul><p>It does not regenerate previews. In lazy mode it acts as a thumbnail and poster prewarm only; preview generation still happens on demand.</p><h2 id="why-derivatives-are-sharded-by-asset-key" tabindex="-1">Why derivatives are sharded by asset key <a class="header-anchor" href="#why-derivatives-are-sharded-by-asset-key" aria-label="Permalink to &quot;Why derivatives are sharded by asset key&quot;">​</a></h2><p>Sharding keeps derivative directories small and decouples cache storage from the gallery tree. That lets Foldergram:</p><ul><li>preserve the same thumbnail and preview paths when a media item is moved</li><li>migrate existing derivatives in place instead of regenerating everything</li><li>garbage-collect stale derivatives by indexed asset reference instead of by mirrored folder tree</li></ul><h2 id="carousel-items" tabindex="-1">Carousel items <a class="header-anchor" href="#carousel-items" aria-label="Permalink to &quot;Carousel items&quot;">​</a></h2><p>Every included carousel item uses the normal thumbnail, preview, poster, and lazy-generation pipeline. Position 1 supplies the feed/grid cover; later items are fitted inside the shared stage without modifying originals. Only the first 20 naturally sorted supported files are indexed, and skipped extras do not enter derivative queues.</p>',87)])])}const m=a(d,[["render",o]]);export{u as __pageData,m as default};
